    if head == nil || head.Next == nil {
        return head
    }

    newHead := ReverseRecursive(head.Next)
    head.Next.Next = head
    head.Next = nil

    return newHead
}
```

La versión iterativa es preferible porque usa O(1) de espacio de pila.

